const items = $input.all();

// Normaliza texto para comparar sin acentos ni mayúsculas
function normalizeText(str) {
  return String(str || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

// Busca una columna por type, title o id
function findColumn(cols, { types = [], titleIncludes = [], idIncludes = [] }) {
  return cols.find((c) => {
    const type = normalizeText(c.type);
    const title = normalizeText(c.column?.title);
    const id = normalizeText(c.id);

    const typeMatch = types.some((t) => type === normalizeText(t));
    const titleMatch = titleIncludes.some((t) => title.includes(normalizeText(t)));
    const idMatch = idIncludes.some((t) => id.includes(normalizeText(t)));

    return typeMatch || titleMatch || idMatch;
  });
}

// Convierte c.value si viene como JSON string
function parseColumnValue(col) {
  if (!col || !col.value) return null;

  try {
    return JSON.parse(col.value);
  } catch {
    return col.value;
  }
}

const output = items.map((entry) => {
  const item = entry.json;
  const cols = item.column_values || [];

  // --------------------
  // EMAIL
  // --------------------
  const emailCol = findColumn(cols, {
    types: ["email"],
    titleIncludes: ["email", "e-mail", "correo", "mail"],
    idIncludes: ["email", "mail"]
  });

  const emailParsed = parseColumnValue(emailCol);

  let email = "";
  if (emailParsed && typeof emailParsed === "object" && emailParsed.email) {
    email = emailParsed.email;
  } else if (emailCol?.text) {
    email = emailCol.text;
  }

  email = String(email || "").trim().toLowerCase();

  // Validación opcional de email
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    email = "";
  }

  // --------------------
  // PHONE
  // --------------------
  const phoneCol = findColumn(cols, {
    types: ["phone"],
    titleIncludes: ["telefono", "teléfono", "tel", "phone", "whatsapp", "celular", "movil", "móvil"],
    idIncludes: ["phone", "telefono", "tel", "whatsapp", "cel"]
  });

  const phoneParsed = parseColumnValue(phoneCol);

  let phone = "";
  if (phoneParsed && typeof phoneParsed === "object" && phoneParsed.phone) {
    phone = phoneParsed.phone;
  } else if (phoneCol?.text) {
    phone = phoneCol.text;
  }

  phone = String(phone || "").replace(/[^\d+]/g, "");

  // --------------------
  // NAME
  // --------------------
  const rawName = String(item.name || "").trim();
  const parts = rawName.split(/\s+/).filter(Boolean);

  const firstName = parts.shift() || "";
  const lastName = parts.join(" ");

  return {
    json: {
      email,
      phone,
      firstName,
      lastName,
      itemId: String(item.id || "")
    }
  };
});

return output;

// --- MD5 SIN crypto (compatible con n8n sandbox) ---
function md5(str) {
  function L(k, d) { return (k << d) | (k >>> (32 - d)); }
  function K(G, k) {
    let I, d, F, H, x;
    F = G & 2147483648;
    H = k & 2147483648;
    I = G & 1073741824;
    d = k & 1073741824;
    x = (G & 1073741823) + (k & 1073741823);
    if (I & d) return x ^ 2147483648 ^ F ^ H;
    if (I | d) {
      if (x & 1073741824) return x ^ 3221225472 ^ F ^ H;
      return x ^ 1073741824 ^ F ^ H;
    }
    return x ^ F ^ H;
  }
  function r(d, F, k) { return (d & F) | (~d & k); }
  function q(d, F, k) { return (d & k) | (F & ~k); }
  function p(d, F, k) { return d ^ F ^ k; }
  function n(d, F, k) { return F ^ (d | ~k); }
  function u(G, F, aa, Z, k, H, I) { G = K(G, K(K(r(F, aa, Z), k), I)); return K(L(G, H), F); }
  function f(G, F, aa, Z, k, H, I) { G = K(G, K(K(q(F, aa, Z), k), I)); return K(L(G, H), F); }
  function D(G, F, aa, Z, k, H, I) { G = K(G, K(K(p(F, aa, Z), k), I)); return K(L(G, H), F); }
  function t(G, F, aa, Z, k, H, I) { G = K(G, K(K(n(F, aa, Z), k), I)); return K(L(G, H), F); }
  function E(G) {
    let Z, k = G.length, x = k + 8, I = (x - (x % 64)) / 64 + 1, aa = new Array(I * 16 - 1);
    let d = 0, F = 0;
    while (F < k) {
      Z = (F - (F % 4)) / 4;
      d = (F % 4) * 8;
      aa[Z] = aa[Z] | (G.charCodeAt(F) << d);
      F++;
    }
    Z = (F - (F % 4)) / 4;
    d = (F % 4) * 8;
    aa[Z] = aa[Z] | (128 << d);
    aa[I * 16 - 2] = k << 3;
    aa[I * 16 - 1] = k >>> 29;
    return aa;
  }
  function B(x) {
    let k = "", F = "", d;
    for (d = 0; d <= 3; d++) {
      F = (x >>> (d * 8)) & 255;
      F = "0" + F.toString(16);
      k += F.substr(F.length - 2, 2);
    }
    return k;
  }
  function J(G) {
    G = G.replace(/\r\n/g, "\n");
    let d = "";
    for (let F = 0; F < G.length; F++) {
      let x = G.charCodeAt(F);
      if (x < 128) d += String.fromCharCode(x);
      else if (x < 2048) {
        d += String.fromCharCode((x >> 6) | 192);
        d += String.fromCharCode((x & 63) | 128);
      } else {
        d += String.fromCharCode((x >> 12) | 224);
        d += String.fromCharCode(((x >> 6) & 63) | 128);
        d += String.fromCharCode((x & 63) | 128);
      }
    }
    return d;
  }

  let aa = [], G, F, k, Z, H, I, d, x;
  str = J(str);
  aa = E(str);
  G = 1732584193;
  F = 4023233417;
  k = 2562383102;
  Z = 271733878;

  for (let o = 0; o < aa.length; o += 16) {
    H = G; I = F; d = k; x = Z;
    G = u(G, F, k, Z, aa[o + 0], 7, 3614090360);
    Z = u(Z, G, F, k, aa[o + 1], 12, 3905402710);
    F = u(F, Z, G, F, aa[o + 2], 17, 606105819);
    k = u(k, F, Z, G, aa[o + 3], 22, 3250441966);
    G = u(G, F, k, Z, aa[o + 4], 7, 4118548399);
    Z = u(Z, G, F, k, aa[o + 5], 12, 1200080426);
    F = u(F, Z, G, F, aa[o + 6], 17, 2821735955);
    k = u(k, F, Z, G, aa[o + 7], 22, 4249261313);
    G = f(G, F, k, Z, aa[o + 8], 7, 1770035416);
    Z = f(Z, G, F, k, aa[o + 9], 12, 2336552879);
    F = f(F, Z, G, F, aa[o + 10], 17, 4294925233);
    k = f(k, F, Z, G, aa[o + 11], 22, 2304563134);
    G = D(G, F, k, Z, aa[o + 12], 7, 1804603682);
    Z = D(Z, G, F, k, aa[o + 13], 12, 4254626195);
    F = D(F, Z, G, F, aa[o + 14], 17, 2792965006);
    k = D(k, F, Z, G, aa[o + 15], 22, 1236535329);
    G = t(G, F, k, Z, aa[o + 0], 7, 4129170786);
    Z = t(Z, G, F, k, aa[o + 7], 12, 3225465664);
    F = t(F, Z, G, F, aa[o + 14], 17, 643717713);
    k = t(k, F, Z, G, aa[o + 5], 22, 3921069994);
    G = t(G, F, k, Z, aa[o + 12], 7, 3593408605);
    Z = t(Z, G, F, k, aa[o + 3], 12, 38016083);
    F = t(F, Z, G, F, aa[o + 10], 17, 3634488961);
    k = t(k, F, Z, G, aa[o + 1], 22, 3889429448);
    G = t(G, F, k, Z, aa[o + 8], 7, 568446438);
    Z = t(Z, G, F, k, aa[o + 15], 12, 3275163606);
    F = t(F, Z, G, F, aa[o + 6], 17, 4107603335);
    k = t(k, F, Z, G, aa[o + 13], 22, 1163531501);
    G = K(G, H); F = K(F, I); k = K(k, d); Z = K(Z, x);
  }

  return (B(G) + B(F) + B(k) + B(Z)).toLowerCase();
}

const items = $input.all();

return items.map((item) => {
  const email = String(item.json.email || "").trim().toLowerCase();

  return {
    json: {
      itemId: item.json.itemId || "",
      email,
      phone: item.json.phone || "",
      firstName: item.json.firstName || "",
      lastName: item.json.lastName || "",
      subscriberHash: md5(email),
    }
  };
});

const items = $input.all();
const seen = new Set();
const output = [];

for (const item of items) {
  const email = String(item.json.email || "").trim().toLowerCase();

  if (!email) continue;
  if (seen.has(email)) continue;

  seen.add(email);
  output.push(item);
}

return output;

const mondayItems = $('Generar Hash Mailchimp').all();
const mailchimpItems = $('Get many members').all();

function normalizeEmail(email) {
  return String(email || '').trim().toLowerCase();
}

const existingHashes = new Set();
const existingEmails = new Set();

for (const item of mailchimpItems) {
  const json = item.json || {};

  if (json.id) {
    existingHashes.add(String(json.id).trim().toLowerCase());
  }

  if (json.email_address) {
    existingEmails.add(normalizeEmail(json.email_address));
  }
}

const output = [];

for (const item of mondayItems) {
  const json = item.json || {};
  const subscriberHash = String(json.subscriberHash || '').trim().toLowerCase();
  const email = normalizeEmail(json.email);

  const exists =
    existingHashes.has(subscriberHash) ||
    existingEmails.has(email);

  output.push({
    json: {
      ...json,
      existsInMailchimp: exists,
      syncAction: exists ? 'update' : 'create'
    }
  });
}

return output;
